// A custom clipper which creates a centered top arc (a single curve) for the
// top edge of the clipped widget. curveHeight controls how deep the arc is.
class _TopCurveClipper extends CustomClipper<Path> {
  final double curveHeight;
  _TopCurveClipper({this.curveHeight = 80});

  @override
  Path getClip(Size size) {
    final Path path = Path();

    // Start at the top-left corner. The curve will be drawn below the top
    // edge so we avoid any negative coordinates which would cause the arc to
    // render above the container and visually overflow.
    path.moveTo(0, 0);
    // Move down to the point where the arc should begin
    path.lineTo(0, curveHeight);

    // Draw a quadratic bezier from left to right across the top with a control
    // point at the top edge (y = 0). This keeps the whole curve within the
    // container bounds and prevents the arc from extending above the screen.
    final double cx = size.width / 2;
    path.quadraticBezierTo(cx, 0, size.width, curveHeight);

    // Continue to bottom-right and close
    path.lineTo(size.width, 0);
    path.lineTo(size.width, size.height);
    path.lineTo(0, size.height);
    path.close();

    return path;
  }

  @override
  bool shouldReclip(covariant CustomClipper<Path> oldClipper) => false;
}

