  const _FlagButton({required this.currentAsset, required this.onSelected, this.preserveFocus});

  @override
  State<_FlagButton> createState() => _FlagButtonState();
}

class _FlagButtonState extends State<_FlagButton> {
  final LayerLink _layerLink = LayerLink();
  OverlayEntry? _overlayEntry;
  final GlobalKey _buttonKey = GlobalKey();

  void _removeOverlay() {
    _overlayEntry?.remove();
    _overlayEntry = null;
  }

  void _showOverlay() {
    // Remember previous focus
    final hadFocus = widget.preserveFocus?.hasFocus ?? false;

    _overlayEntry = OverlayEntry(builder: (context) {
      // compute button height to offset the follower
      double buttonHeight = 0;
      final btnContext = _buttonKey.currentContext;
      if (btnContext != null) {
        final rb = btnContext.findRenderObject();
        if (rb is RenderBox) buttonHeight = rb.size.height;
      }

      return Positioned.fill(
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onTap: () {
            _removeOverlay();
            if (hadFocus && (widget.preserveFocus != null)) {
              Future.microtask(() => widget.preserveFocus!.requestFocus());
            }
          },
          child: Material(
            color: Colors.transparent,
            child: Stack(
              children: [
                CompositedTransformFollower(
                  link: _layerLink,
                  showWhenUnlinked: false,
                  offset: Offset(0, buttonHeight),
                  child: Material(
                    elevation: 8,
                    color: Theme.of(context).cardColor,
                    borderRadius: BorderRadius.circular(8),
                    child: ConstrainedBox(
                      constraints: BoxConstraints(minWidth: 150, maxWidth: 280),
                      child: IntrinsicWidth(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: List.generate(3, (i) {
                            return InkWell(
                              onTap: () {
                                widget.onSelected('assets/images/flags/algeria.svg');
                                _removeOverlay();
                                if (hadFocus && (widget.preserveFocus != null)) {
                                  Future.microtask(() => widget.preserveFocus!.requestFocus());
                                }
                              },
                              child: Padding(
                                padding: const EdgeInsets.symmetric(horizontal: 12.0, vertical: 10.0),
                                child: Row(
                                  children: [
                                    FlagImage.asset('assets/images/flags/algeria.svg', width: 28, height: 20),
                                    const SizedBox(width: 12),
                                    Text('Algeria'),
                                  ],
                                ),
                              ),
                            );
                          }),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    });

  Overlay.of(context).insert(_overlayEntry!);
  }

  @override
  void dispose() {
    _removeOverlay();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return CompositedTransformTarget(
      link: _layerLink,
      child: SizedBox(
        width: double.infinity,
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            key: _buttonKey,
            borderRadius: BorderRadius.circular(8),
            onTapDown: (_) {
              try {
                widget.preserveFocus?.requestFocus();
              } catch (_) {}
            },
            onTap: () {
              // Toggle overlay
              if (_overlayEntry == null) {
                _showOverlay();
              } else {
                _removeOverlay();
              }
            },
            child: LayoutBuilder(
              builder: (context, constraints) {
                const neededWidth = 64.0; // flag(28)+spacing(8)+icon(16)+inner padding(12)
                final content = Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 6.0, vertical: 8.0),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      FlagImage.asset(widget.currentAsset, width: 28, height: 20),
                      const SizedBox(width: 8),
                      Icon(
                        Icons.keyboard_arrow_up,
                        size: 16,
                        color: Theme.of(context).iconTheme.color ?? Colors.red,
                      ),
                    ],
                  ),
                );

                if (constraints.maxWidth.isFinite && constraints.maxWidth < neededWidth) {
                  return FittedBox(fit: BoxFit.scaleDown, alignment: Alignment.centerLeft, child: content);
                }

                // Ensure the entire available width is tappable by placing the
                // content inside a Row that aligns to the start but expands.
                return Row(
                  mainAxisSize: MainAxisSize.max,
                  children: [
                    content,
                    const Spacer(),
                  ],
                );
              },
            ),
          ),
        ),
      ),
    );
  }
}

class _CountryCodeSelectorState extends State<_CountryCodeSelector> {
  late String _code;

  final List<Map<String, String>> _options = const [
    {'code': '+213', 'label': 'DZ'},
    {'code': '+33', 'label': 'FR'},
    {'code': '+1', 'label': 'US'},
  ];

  @override
  void initState() {
    super.initState();
    _code = widget.initial;
  }

  @override
  Widget build(BuildContext context) {
    return DropdownButtonHideUnderline(
      child: DropdownButton<String>(
        value: _code,
        items: _options
            .map((e) => DropdownMenuItem(
                  value: e['code'],
                  child: Row(
                    children: [
                      Text(e['label'] ?? ''),
                      const SizedBox(width: 6),
                      Text(e['code'] ?? ''),
                    ],
                  ),
                ))
            .toList(),
        onChanged: (v) {
          if (v == null) return;
          setState(() => _code = v);
          widget.onChanged(v);
        },
      ),
    );
  }
}
